from decimal import Decimal, localcontext, ROUND_HALF_UP
import datetime
import calendar
import re

def amortize(principal: str, annual_rate_percent: str, months: int, start_date: str) -> list[dict]:
    # validate principal
    if not isinstance(principal, str):
        raise ValueError("principal must be str")
    try:
        p = Decimal(principal)
    except Exception:
        raise ValueError("invalid principal")
    if not p.is_finite():
        raise ValueError("principal must be finite")
    if p <= 0:
        raise ValueError("principal must be > 0")
    try:
        exp = p.as_tuple().exponent
    except Exception:
        raise ValueError("invalid principal")
    if not isinstance(exp, int) or exp < -2:
        raise ValueError("principal at most 2 decimals")
    # validate rate
    if not isinstance(annual_rate_percent, str):
        raise ValueError("rate must be str")
    try:
        rate = Decimal(annual_rate_percent)
    except Exception:
        raise ValueError("invalid rate")
    if not rate.is_finite():
        raise ValueError("rate must be finite")
    if rate < 0 or rate > 100:
        raise ValueError("rate out of range")
    # validate months
    if isinstance(months, bool) or not isinstance(months, int):
        raise ValueError("months must be int")
    if not 1 <= months <= 360:
        raise ValueError("months out of range")
    # validate start_date
    if not isinstance(start_date, str):
        raise ValueError("start_date must be str")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date):
        raise ValueError("bad date format")
    try:
        ys, ms, ds = start_date.split("-")
        sy = int(ys)
        sm = int(ms)
        sd = int(ds)
        datetime.date(sy, sm, sd)
    except Exception:
        raise ValueError("invalid date")
    anchor = sd
    CENT = Decimal("0.01")
    with localcontext() as ctx:
        ctx.prec = 50
        r = rate / Decimal(1200)
        principal_q = p.quantize(CENT, rounding=ROUND_HALF_UP)
        if r == 0:
            level = (principal_q / Decimal(months)).quantize(CENT, rounding=ROUND_HALF_UP)
        else:
            one = Decimal(1)
            denom = one - ((one + r) ** (-months))
            level = (principal_q * r / denom).quantize(CENT, rounding=ROUND_HALF_UP)
        schedule = []
        opening = principal_q
        for n in range(1, months + 1):
            tot = (sm - 1) + n
            ty = sy + tot // 12
            tm = tot % 12 + 1
            try:
                last = calendar.monthrange(ty, tm)[1]
            except Exception:
                raise ValueError("date out of range")
            try:
                dday = anchor if anchor <= last else last
                datetime.date(ty, tm, dday)
            except Exception:
                raise ValueError("date out of range")
            date_str = f"{ty:04d}-{tm:02d}-{dday:02d}"
            interest = (opening * r).quantize(CENT, rounding=ROUND_HALF_UP)
            if n < months:
                payment = level
                princ = (payment - interest).quantize(CENT, rounding=ROUND_HALF_UP)
                bal = (opening - princ).quantize(CENT, rounding=ROUND_HALF_UP)
            else:
                princ = opening.quantize(CENT, rounding=ROUND_HALF_UP) if opening is not None else Decimal("0.00")
                payment = (opening + interest).quantize(CENT, rounding=ROUND_HALF_UP)
                bal = Decimal("0.00")
            schedule.append({"n": n, "date": date_str, "payment": payment, "interest": interest, "principal": princ, "balance": bal})
            opening = bal
        return schedule

def total_interest(schedule) -> Decimal:
    CENT = Decimal("0.01")
    if not schedule:
        return Decimal("0.00")
    total = sum((row["interest"] for row in schedule), Decimal("0.00"))
    return total.quantize(CENT, rounding=ROUND_HALF_UP)
